/* HTMX Minimal Runtime for PocketPDV */
(function() {
  function parseVals(valsAttr) {
    if (!valsAttr) return "";
    var trimmed = valsAttr.trim();
    if (trimmed.startsWith("{") && trimmed.endsWith("}")) {
      try {
        var obj = JSON.parse(trimmed);
        var params = new URLSearchParams();
        for (var key in obj) {
          if (Object.prototype.hasOwnProperty.call(obj, key)) {
            params.append(key, obj[key]);
          }
        }
        return params.toString();
      } catch (e) {
        console.warn("Falha ao analisar hx-vals como JSON:", e);
      }
    }
    return trimmed;
  }

  function executeScripts(container) {
    if (!container) return;
    var scripts = container.querySelectorAll("script");
    scripts.forEach(function(oldScript) {
      var newScript = document.createElement("script");
      Array.from(oldScript.attributes).forEach(function(attr) {
        newScript.setAttribute(attr.name, attr.value);
      });
      newScript.appendChild(document.createTextNode(oldScript.innerHTML));
      oldScript.parentNode.replaceChild(newScript, oldScript);
    });
  }

  function processHtmxResponse(html, targetEl) {
    var template = document.createElement("template");
    template.innerHTML = (html || "").trim();

    // 1. Processar elementos Out-of-Band (OOB)
    var oobElements = template.content.querySelectorAll("[hx-swap-oob='true']");
    oobElements.forEach(function(oob) {
      var targetId = oob.getAttribute("id");
      if (targetId) {
        var existing = document.getElementById(targetId);
        if (existing) {
          var clone = oob.cloneNode(true);
          clone.removeAttribute("hx-swap-oob");
          existing.outerHTML = clone.outerHTML;
        }
      }
      oob.remove();
    });

    // 2. Alvo primário de substituição
    if (targetEl) {
      targetEl.innerHTML = "";
      while (template.content.firstChild) {
        targetEl.appendChild(template.content.firstChild);
      }
      executeScripts(targetEl);
    } else {
      // Se não houver alvo primário mas houver scripts soltos no retorno
      var tempDiv = document.createElement("div");
      tempDiv.appendChild(template.content);
      executeScripts(tempDiv);
    }
  }

  function initHtmx() {
    // Interceptar envio de formulários com hx-post
    document.addEventListener("submit", function(e) {
      var form = e.target;
      var postUrl = form.getAttribute("hx-post");
      if (!postUrl) return;

      e.preventDefault();
      var confirmMsg = form.getAttribute("hx-confirm");
      if (confirmMsg && !confirm(confirmMsg)) return;

      var targetSel = form.getAttribute("hx-target");
      var targetEl = targetSel ? document.querySelector(targetSel) : null;
      var formData = new FormData(form);
      var params = new URLSearchParams();
      for (var pair of formData.entries()) {
        params.append(pair[0], pair[1]);
      }

      var extraVals = parseVals(form.getAttribute("hx-vals"));
      var bodyData = params.toString();
      if (extraVals) {
        bodyData = bodyData ? bodyData + "&" + extraVals : extraVals;
      }

      var xhr = new XMLHttpRequest();
      xhr.open("POST", postUrl, true);
      xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
      xhr.setRequestHeader("HX-Request", "true");
      xhr.onreadystatechange = function() {
        if (xhr.readyState === 4) {
          var redirectUrl = xhr.getResponseHeader("HX-Redirect");
          if (redirectUrl) {
            window.location.href = redirectUrl;
            return;
          }
          if (xhr.status >= 200 && xhr.status < 300) {
            processHtmxResponse(xhr.responseText, targetEl);
            form.reset();
          } else if (xhr.status === 401) {
            window.location.href = "/login";
          } else {
            alert("Erro ao processar formulário: " + xhr.status + " " + xhr.responseText);
          }
        }
      };
      xhr.send(bodyData);
    });

    // Interceptar cliques em elementos com hx-delete, hx-post ou hx-get
    document.addEventListener("click", function(e) {
      var targetNode = e.target;

      // Tratar hx-delete
      var deleteBtn = targetNode.closest("[hx-delete]");
      if (deleteBtn) {
        e.preventDefault();
        var confirmMsg = deleteBtn.getAttribute("hx-confirm");
        if (confirmMsg && !confirm(confirmMsg)) return;

        var deleteUrl = deleteBtn.getAttribute("hx-delete");
        var targetSel = deleteBtn.getAttribute("hx-target");
        var targetEl = targetSel ? document.querySelector(targetSel) : null;

        var xhr = new XMLHttpRequest();
        xhr.open("DELETE", deleteUrl, true);
        xhr.setRequestHeader("HX-Request", "true");
        xhr.onreadystatechange = function() {
          if (xhr.readyState === 4) {
            if (xhr.status >= 200 && xhr.status < 300) {
              processHtmxResponse(xhr.responseText, targetEl);
            } else if (xhr.status === 401) {
              window.location.href = "/login";
            }
          }
        };
        xhr.send();
        return;
      }

      // Tratar hx-post em botões fora de submit de form
      var postBtn = targetNode.closest("[hx-post]");
      if (postBtn && postBtn.tagName !== "FORM") {
        e.preventDefault();
        var confirmMsg = postBtn.getAttribute("hx-confirm");
        if (confirmMsg && !confirm(confirmMsg)) return;

        var postUrl = postBtn.getAttribute("hx-post");
        var targetSel = postBtn.getAttribute("hx-target");
        var targetEl = targetSel ? document.querySelector(targetSel) : null;
        var bodyData = parseVals(postBtn.getAttribute("hx-vals"));

        var xhr = new XMLHttpRequest();
        xhr.open("POST", postUrl, true);
        xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
        xhr.setRequestHeader("HX-Request", "true");
        xhr.onreadystatechange = function() {
          if (xhr.readyState === 4) {
            var redirectUrl = xhr.getResponseHeader("HX-Redirect");
            if (redirectUrl) {
              window.location.href = redirectUrl;
              return;
            }
            if (xhr.status >= 200 && xhr.status < 300) {
              processHtmxResponse(xhr.responseText, targetEl);
            } else if (xhr.status === 401) {
              window.location.href = "/login";
            } else {
              alert("Erro ao processar requisição: " + xhr.status);
            }
          }
        };
        xhr.send(bodyData);
        return;
      }

      // Tratar hx-get em botões ou links
      var getBtn = targetNode.closest("[hx-get]");
      if (getBtn) {
        e.preventDefault();
        var getUrl = getBtn.getAttribute("hx-get");
        var targetSel = getBtn.getAttribute("hx-target");
        var targetEl = targetSel ? document.querySelector(targetSel) : null;

        var xhr = new XMLHttpRequest();
        xhr.open("GET", getUrl, true);
        xhr.setRequestHeader("HX-Request", "true");
        xhr.onreadystatechange = function() {
          if (xhr.readyState === 4) {
            if (xhr.status >= 200 && xhr.status < 300) {
              processHtmxResponse(xhr.responseText, targetEl);
            } else if (xhr.status === 401) {
              window.location.href = "/login";
            }
          }
        };
        xhr.send();
        return;
      }
    });
  }

  window.addEventListener("DOMContentLoaded", initHtmx);
})();
